import{_ as i,a0 as p,w as s,s as d,I as e,x as t,a1 as r,A as n,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"如何为Linux系统中的SSH添加双重认证 | LCTT x X-CMD","titleTemplate":false,"description":"如何为Linux系统中的SSH添加双重认证 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何为Linux系统中的SSH添加双重认证 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何为Linux系统中的SSH添加双重认证 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140709 How to set up two-factor authentication for SSH login on Linux","title":"如何为Linux系统中的SSH添加双重认证","tag":"201408","desc":""},"relativePath":"201408/20140709 How to set up two-factor authentication for SSH login on Linux.md","filePath":"[post].md"}'),u={name:"201408/20140709 How to set up two-factor authentication for SSH login on Linux.md"};function g(m,o,h,c,f,x){const a=p("Link");return s(),d("div",null,[o[29]||(o[29]=e("h1",{id:"如何为linux系统中的ssh添加双重认证",tabindex:"-1"},[t("如何为Linux系统中的SSH添加双重认证 "),e("a",{class:"header-anchor",href:"#如何为linux系统中的ssh添加双重认证","aria-label":"Permalink to “如何为Linux系统中的SSH添加双重认证”"},"​")],-1)),o[30]||(o[30]=e("p",null,"近来很多知名企业都出现了密码泄露，业内对多重认证的呼声也越来越高。在这种多重认证的系统中，用户需要通过两种不同的认证程序：提供他们知道的信息（如 用户名/密码），再借助其他工具提供用户所不知道的信息（如 用手机生成的一次性密码）。这种组合方式常叫做双因子认证或者两阶段验证。",-1)),e("p",null,[o[3]||(o[3]=t("为了鼓励广泛采用双因子认证的方式，Google公司发布了",-1)),r(a,{href:"http://code.google.com/p/google-authenticator/"},{default:n(()=>[...o[0]||(o[0]=[t("Google Authenticator",-1)])]),_:1}),o[4]||(o[4]=t("，一款开源的，可基于开放规则（如 HMAP/基于时间）生成一次性密码的软件。这是一款跨平台软件，可运行在Linux, ",-1)),r(a,{href:"https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2"},{default:n(()=>[...o[1]||(o[1]=[t("Android",-1)])]),_:1}),o[5]||(o[5]=t(", ",-1)),r(a,{href:"https://itunes.apple.com/us/app/google-authenticator/id388497605"},{default:n(()=>[...o[2]||(o[2]=[t("iOS",-1)])]),_:1}),o[6]||(o[6]=t("。Google公司同时也支持插件式鉴别模块PAM(pluggable authentication module)，使其能和其他也适用PAM进行验证的工具（如OpenSSH）协同工作。",-1))]),e("p",null,[o[8]||(o[8]=t("在本教程中，我们将叙述集成OpenSSH和Google提供的认证器实现",-1)),o[9]||(o[9]=e("strong",null,"如何为SSH服务设置双因子认证",-1)),o[10]||(o[10]=t("。我将使用一款",-1)),r(a,{href:"http://xmodulo.com/go/android_guide"},{default:n(()=>[...o[7]||(o[7]=[t("Android",-1)])]),_:1}),o[11]||(o[11]=t("设备来生成一次性密码，本教程中需要两样武器：(1)一台运行着OpenSSH服务的Linux终端，(2)一台安卓设备。",-1))]),o[31]||(o[31]=l(`<h3 id="在linux系统中安装google-authenticator" tabindex="-1">在Linux系统中安装Google Authenticator <a class="header-anchor" href="#在linux系统中安装google-authenticator" aria-label="Permalink to “在Linux系统中安装Google Authenticator”">​</a></h3><p>第一步需要在运行着OpenSSH服务的Linux主机上安装Google认证器。按照如下步骤安装Google认证器及其PAM模块。</p><h4 id="用安装包安装-google-authenticator" tabindex="-1">用安装包安装 Google Authenticator <a class="header-anchor" href="#用安装包安装-google-authenticator" aria-label="Permalink to “用安装包安装 Google Authenticator”">​</a></h4><p>如果你不想自己构建 Google Authenticator，在几个 Linux 发行版上有已经编译好的安装包。安装包里面包含 Google Authenticator 二进制程序和 PAM 模块。</p><p>在 Ubuntu 上安装 Google Authenticator：</p><pre><code>$ sudo apt-get install libpam-google-authenticator
</code></pre><p>在 Fedora 上安装 Google Authenticator：</p><pre><code>$ sudo yum install google-authenticator
</code></pre><p>在 CentOS 上安装 Google Authenticator ，需要首先启用 EPEL 软件库，然后运行如下命令：</p><pre><code>$ sudo yum install google-authenticator
</code></pre><p>如果不想使用已经编译好的安装包，或者你的 Linux 发行版不在此列，可以自行编译：</p><h4 id="在-linux-上-google-authenticator" tabindex="-1">在 Linux 上 Google Authenticator <a class="header-anchor" href="#在-linux-上-google-authenticator" aria-label="Permalink to “在 Linux 上 Google Authenticator”">​</a></h4><p>首先，安装构建 Google Authenticator 所需的软件包。</p><p>在 Debian、 Ubuntu 或 Linux Mint 上：</p><pre><code>$ sudo apt-get install wget make gcc libpam0g-dev
</code></pre><p>在 CentOS、 Fedora 或 RHEL上：</p><pre><code>$ sudo yum install wget make gcc pam-devel
</code></pre><p>然后下载 Google Authenticator 的源代码，并按如下命令编译。</p><pre><code>$ wget https://google-authenticator.googlecode.com/files/libpam-google-authenticator-1.0-source.tar.bz2
$ tar xvfvj libpam-google-authenticator-1.0-source.tar.bz2
$ cd libpam-google-authenticator-1.0
$ make
</code></pre><p>如果构建成功，你会在目录中看到 pam_google_authenticator.so 和 google-authenticator 两个文件。</p><p>最后，将 Google Authenticator 安装到合适位置</p><pre><code>$ sudo make install
</code></pre><h4 id="排错" tabindex="-1">排错 <a class="header-anchor" href="#排错" aria-label="Permalink to “排错”">​</a></h4><p>当编译 Google Authenticator 时出现如下错误：</p><pre><code>fatal error: security/pam_appl.h: No such file or directory
</code></pre><p>要修复这个问题，请安装如下依赖包。</p><p>在 Debian、 Ubuntu 或 Linux Mint 上：</p><pre><code>$ sudo apt-get install libpam0g-dev
</code></pre><p>在 CentOS、 Fedora 或 RHEL 上：</p><pre><code>$ sudo yum install pam-devel
</code></pre><p>当Google认证器安装好后，你需要在Linux主机上创建验证密钥，并且在安卓设备上注册，注意这项配置操作是一次性的。我们将详细叙述如何完成这些操作：</p><h3 id="生成验证密钥" tabindex="-1">生成验证密钥 <a class="header-anchor" href="#生成验证密钥" aria-label="Permalink to “生成验证密钥”">​</a></h3><p>在Linux主机上运行Google认证器</p><pre><code>$ google-authenticator 
</code></pre><p>你将看到一个QR码，它使用如下图形表示我们数字形态的密钥。一会我们要用到它在安卓设备上完成配置。</p><p><img src="https://farm4.staticflickr.com/3843/14573264401_d3f5a2f247_z.jpg" alt=""><img src="https://farm4.staticflickr.com/3848/14390010599_18dfc23d76_z.jpg" alt=""></p><p>Google认证器会问一些问题，如果你不确定，就回答&quot;Yes&quot;。这个应急备用验证码(图中 emergency scratch codes）可以在你由于丢失了绑定的安卓设备的情况下（所以不能得到生成的一次性密码）恢复访问。最好将应急备用验证码妥善保存。</p><h3 id="在安卓设备上运行google认证器" tabindex="-1">在安卓设备上运行Google认证器 <a class="header-anchor" href="#在安卓设备上运行google认证器" aria-label="Permalink to “在安卓设备上运行Google认证器”">​</a></h3>`,38)),e("p",null,[o[13]||(o[13]=t("我们需要在安卓设备上安装",-1)),r(a,{href:"https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2"},{default:n(()=>[...o[12]||(o[12]=[t("Google Authenticator app",-1)])]),_:1}),o[14]||(o[14]=t("才能完成双因子认证，到Google Play下载并安装一个。在安卓设备上运行Google认证器，找到下图所示中的配置菜单。",-1))]),o[32]||(o[32]=e("p",null,[e("img",{src:"https://farm6.staticflickr.com/5574/14554094476_bfc070d242_z.jpg",alt:""})],-1)),e("p",null,[o[16]||(o[16]=t('你可以选择"Scan a barcode" 或者"Enter provided key"选项。"Scan a barcode"允许你扫描QR码来完成密钥的输入，在此可能需要先安装扫描软件',-1)),r(a,{href:"https://play.google.com/store/apps/details?id=com.google.zxing.client.android"},{default:n(()=>[...o[15]||(o[15]=[t("Barcode Scanner app",-1)])]),_:1}),o[17]||(o[17]=t('。如果选择"Enter provided key"选项，你可以使用键盘输入验证密钥，如下图所示：',-1))]),o[33]||(o[33]=l(`<p><img src="https://farm6.staticflickr.com/5535/14596723603_d510dbe48d_z.jpg" alt=""></p><p>无论采用上述两种选项的任何方式，一旦成功，你将看到注册成功提示和一次性密码，如下图所示：</p><p><img src="https://farm6.staticflickr.com/5586/14390009579_5ba109bf5b_z.jpg" alt=""></p><h3 id="为ssh服务器用google认证器" tabindex="-1">为SSH服务器用Google认证器 <a class="header-anchor" href="#为ssh服务器用google认证器" aria-label="Permalink to “为SSH服务器用Google认证器”">​</a></h3><p>最终我们需要修改两个文件来完成集成Google认证器和OpenSSH服务这临门一脚。</p><p>首先，修改PAM配置文件，命令和需添加的内容如下：</p><pre><code>$ sudo vi /etc/pam.d/sshd 
</code></pre><hr><pre><code>auth required pam_google_authenticator.so
</code></pre><p>然后打开SSH配置文件，找到参数ChallengeResponseAuthentication，并启用它。</p><pre><code>$ sudo vi /etc/ssh/sshd_config 
</code></pre><hr><p>ChallengeResponseAuthentication yes</p><p>最后，重启SSH服务。</p><p>在 Ubuntu、 Debian 和 Linux Mint 上：</p><pre><code>$ sudo service ssh restart 
</code></pre><p>在Fedora （或 CentOS/RHEL 7）上：</p><pre><code>$ sudo systemctl restart sshd 
</code></pre><p>在CentOS 6.x或 RHEL 6.x上：</p><pre><code>$ sudo service sshd restart 
</code></pre><h3 id="验证双因子认证" tabindex="-1">验证双因子认证 <a class="header-anchor" href="#验证双因子认证" aria-label="Permalink to “验证双因子认证”">​</a></h3><p>在绑定的安卓设备上运行Google认证器，获得一个一次性验证码，该验证码30秒内有效，一旦过期，将重新生成一个新的验证码。</p><p><img src="https://farm3.staticflickr.com/2937/14389989618_d9355dcbb2_z.jpg" alt=""></p><p>现在和往常一样，使用SSH登录终端</p><pre><code>$ ssh user@ssh_server 
</code></pre><p>当提示你输入验证码的时候，输入我们刚获得的验证码。验证成功后，再输入SSH的登录密码。</p><p><img src="https://farm3.staticflickr.com/2938/14389952480_93351f12a4_z.jpg" alt=""></p><p>双因子认证通过在用户密码前新增一层来有效的保护我们脆弱的用户密码。你可以使用Google认证器来保护我们其他的密码，如Google账户, WordPress.com, Dropbox.com, Outlook.com等等。是否使用这项技术，取决于我们自己，但采用双因子认证已经是行业的大趋势了。</p><hr>`,29)),e("p",null,[o[19]||(o[19]=t("via: ",-1)),r(a,{href:"http://xmodulo.com/2014/07/two-factor-authentication-ssh-login-linux.html"},{default:n(()=>[...o[18]||(o[18]=[t("http://xmodulo.com/2014/07/two-factor-authentication-ssh-login-linux.html",-1)])]),_:1})]),e("p",null,[o[22]||(o[22]=t("译者：",-1)),r(a,{href:"https://github.com/nd0104"},{default:n(()=>[...o[20]||(o[20]=[t("nd0104",-1)])]),_:1}),o[23]||(o[23]=t(" 校对：",-1)),r(a,{href:"https://github.com/wxy"},{default:n(()=>[...o[21]||(o[21]=[t("wxy",-1)])]),_:1})]),e("p",null,[o[26]||(o[26]=t("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...o[24]||(o[24]=[t("LCTT",-1)])]),_:1}),o[27]||(o[27]=t(" 原创翻译，",-1)),r(a,{href:"http://linux.cn/"},{default:n(()=>[...o[25]||(o[25]=[t("Linux中国",-1)])]),_:1}),o[28]||(o[28]=t(" 荣誉推出",-1))])])}const G=i(u,[["render",g]]);export{L as __pageData,G as default};
